<?php require_once __DIR__.'/../config/db.php';$pdo=db();if(!user_can($pdo,'content'))redirect('admin/');if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf($_POST['csrf']??null)){if(isset($_POST['banner'])){$st=$pdo->prepare('INSERT INTO banners(title,subtitle,image,link,is_active,sort_order) VALUES(?,?,?,?,?,?)');$st->execute([trim($_POST['title']),trim($_POST['subtitle']),trim($_POST['image']),trim($_POST['link']),1,(int)$_POST['sort_order']]);}if(isset($_POST['popup'])){$pdo->query('UPDATE popups SET is_active=0');$st=$pdo->prepare('INSERT INTO popups(title,message,button_text,button_url,is_active,start_at,end_at) VALUES(?,?,?,?,1,?,?)');$st->execute([trim($_POST['ptitle']),trim($_POST['message']),trim($_POST['button_text']),trim($_POST['button_url']),$_POST['start_at']?:null,$_POST['end_at']?:null]);}flash('success','Content saved.');redirect('admin/content.php');}$banners=$pdo->query('SELECT * FROM banners ORDER BY id DESC')->fetchAll();$title='Content | Admin';include __DIR__.'/../includes/header.php';?><section class="container admin"><div class="admin-head"><div><span class="eyebrow">CONTENT</span><h1>Banner & popup</h1></div></div><div class="panel"><h2>Homepage banner</h2><p class="hint">Title and subtitle appear as floating text on the left half. The banner image appears on the right half, so use a farm/fresh-food visual.</p><form class="settings-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="banner" value="1"><label>Title<input name="title"></label><label>Subtitle<input name="subtitle"></label><label>Image path/URL<input name="image" value="assets/images/banners/hero-farm-home.svg" required></label><label>Link<input name="link"></label><label>Sort order<input type="number" name="sort_order" value="1"></label><button class="btn btn-primary">Add banner</button></form></div><div class="panel"><h2>Important popup</h2><form class="settings-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="popup" value="1"><label>Title<input name="ptitle" required></label><label>Message<textarea name="message" required></textarea></label><label>Button text<input name="button_text"></label><label>Button URL<input name="button_url"></label><label>Start<input type="datetime-local" name="start_at"></label><label>End<input type="datetime-local" name="end_at"></label><button class="btn btn-primary">Publish popup</button></form></div><div class="panel"><h2>Current banners</h2><?php foreach($banners as $b):?><div class="address-card"><b><?=e($b['title']?:'Untitled')?></b> — <?=e($b['image'])?></div><?php endforeach;?></div></section><?php include __DIR__.'/../includes/footer.php';?>
